function stepsToZero(n: number): number {
  const memo = new Map<number, number>();
  const solve = (x: number): number => {
    if ((x & (x - 1)) === 0) return 1; // x is a power of two
    const hit = memo.get(x);
    if (hit !== undefined) return hit;
    const low = x & -x;
    const best = 1 + Math.min(solve(x - low), solve(x + low));
    memo.set(x, best);
    return best;
  };
  return solve(n);
}

