function stepsToZero(n: number): number {
  let steps = 0;
  while (n > 0) {
    if ((n & 3) === 3) {
      n += 1;
      steps++;
    } else if (n & 1) {
      n -= 1;
      steps++;
    } else {
      n >>= 1;
    }
  }
  return steps;
}

